USE [JamunaBankProcurement];
GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Requisition_Create @RequisitionNo VARCHAR(30),@RequestedByEmployeeId VARCHAR(30),@RequestedOrgUnitId BIGINT,@Justification NVARCHAR(2000),@Items dbo.RequisitionItemTableType READONLY,@Actor VARCHAR(50)
AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRY BEGIN TRAN; IF NOT EXISTS(SELECT 1 FROM @Items) THROW 51000,'At least one item is required.',1; IF EXISTS(SELECT 1 FROM @Items WHERE REQ_TYPE NOT IN('NEW','REPLACEMENT','ADDITIONAL') OR QUANTITY<=0 OR ESTIMATED_UNIT_PRICE<0 OR (REQ_TYPE='REPLACEMENT' AND NULLIF(CURRENT_CONDITION,'') IS NULL)) THROW 51000,'One or more items are invalid.',1; DECLARE @ResolvedItems dbo.RequisitionItemTableType;INSERT @ResolvedItems(CLIENT_ITEM_KEY,ASSET_ID,REQ_TYPE,QUANTITY,ESTIMATED_UNIT_PRICE,PURPOSE_JUSTIFICATION,ADDITIONAL_SPEC_REQUIREMENT,ASSET_TAG_NO,SERIAL_NO,CURRENT_CONDITION,REPLACEMENT_ADDITIONAL_INFO) SELECT i.CLIENT_ITEM_KEY,i.ASSET_ID,i.REQ_TYPE,i.QUANTITY,CONVERT(DECIMAL(18,2),COALESCE(v.DEFAULT_TOTAL_AMOUNT,0)/NULLIF(i.QUANTITY,0)),i.PURPOSE_JUSTIFICATION,i.ADDITIONAL_SPEC_REQUIREMENT,i.ASSET_TAG_NO,i.SERIAL_NO,i.CURRENT_CONDITION,i.REPLACEMENT_ADDITIONAL_INFO FROM @Items i OUTER APPLY(SELECT MAX(COALESCE(r.MAX_AMOUNT,r.MIN_AMOUNT)) DEFAULT_TOTAL_AMOUNT FROM dbo.WORKFLOW_RULE r WHERE r.ASSET_ID=i.ASSET_ID AND r.REQ_TYPE=i.REQ_TYPE AND r.IS_ACTIVE=1 AND r.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME()) AND(r.EFFECTIVE_TO IS NULL OR r.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())))v;IF EXISTS(SELECT 1 FROM @ResolvedItems WHERE ESTIMATED_UNIT_PRICE<=0) THROW 51000,'No active workflow rule with an amount range is configured for one or more requisition items.',1; INSERT dbo.REQUISITION_HEADER(REQUISITION_NO,REQUESTED_BY_EMPLOYEE_ID,REQUESTED_ORG_UNIT_ID,JUSTIFICATION,TOTAL_ESTIMATED_AMOUNT,CREATED_BY) SELECT @RequisitionNo,@RequestedByEmployeeId,@RequestedOrgUnitId,@Justification,SUM(QUANTITY*ESTIMATED_UNIT_PRICE),@Actor FROM @ResolvedItems; DECLARE @id BIGINT=SCOPE_IDENTITY(); DECLARE @map TABLE(CLIENT_ITEM_KEY INT,REQ_ITEM_ID BIGINT,REQ_TYPE VARCHAR(20),ASSET_TAG_NO NVARCHAR(100),SERIAL_NO NVARCHAR(100),CURRENT_CONDITION NVARCHAR(2000),ADDITIONAL_INFO NVARCHAR(2000)); MERGE dbo.REQUISITION_ITEM AS t USING(SELECT i.*,a.ASSET_NAME FROM @ResolvedItems i JOIN dbo.ASSET_MASTER a ON a.ASSET_ID=i.ASSET_ID AND a.IS_ACTIVE=1) s ON 1=0 WHEN NOT MATCHED THEN INSERT(REQUISITION_ID,ASSET_ID,ITEM_NAME_SNAPSHOT,REQ_TYPE,QUANTITY,ESTIMATED_UNIT_PRICE,PURPOSE_JUSTIFICATION,ADDITIONAL_SPEC_REQUIREMENT,CREATED_BY) VALUES(@id,s.ASSET_ID,s.ASSET_NAME,s.REQ_TYPE,s.QUANTITY,s.ESTIMATED_UNIT_PRICE,s.PURPOSE_JUSTIFICATION,s.ADDITIONAL_SPEC_REQUIREMENT,@Actor) OUTPUT s.CLIENT_ITEM_KEY,inserted.REQ_ITEM_ID,s.REQ_TYPE,s.ASSET_TAG_NO,s.SERIAL_NO,s.CURRENT_CONDITION,s.REPLACEMENT_ADDITIONAL_INFO INTO @map; IF (SELECT COUNT(*) FROM @map)<>(SELECT COUNT(*) FROM @ResolvedItems) THROW 51000,'An asset is missing or inactive.',1; INSERT dbo.REQUISITION_REPLACEMENT_INFO(REQ_ITEM_ID,ASSET_TAG_NO,SERIAL_NO,CURRENT_CONDITION,ADDITIONAL_INFO,CREATED_BY) SELECT REQ_ITEM_ID,ASSET_TAG_NO,SERIAL_NO,CURRENT_CONDITION,ADDITIONAL_INFO,@Actor FROM @map WHERE REQ_TYPE='REPLACEMENT'; INSERT dbo.AUDIT_LOG(ENTITY_NAME,ENTITY_ID,ACTION_TYPE,NEW_VALUE_JSON,ACTION_BY_EMPLOYEE_ID) VALUES('REQUISITION_HEADER',@id,'INSERT',(SELECT @RequisitionNo REQUISITION_NO FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),@RequestedByEmployeeId); COMMIT; SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,@id ENTITY_ID,@RequisitionNo REFERENCE_NO; END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SELECT CASE WHEN ERROR_NUMBER()=51000 THEN '001' WHEN ERROR_NUMBER() IN(2601,2627) THEN '005' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,NULL ENTITY_ID,@RequisitionNo REFERENCE_NO; END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Requisition_GetById @RequisitionId BIGINT AS BEGIN SET NOCOUNT ON; SELECT h.*,o.ORG_UNIT_NAME,u.DISPLAY_NAME REQUESTED_BY_NAME FROM dbo.REQUISITION_HEADER h JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=h.REQUESTED_BY_EMPLOYEE_ID WHERE h.REQUISITION_ID=@RequisitionId; SELECT * FROM dbo.REQUISITION_ITEM WHERE REQUISITION_ID=@RequisitionId ORDER BY REQ_ITEM_ID; SELECT s.*,o.ASSET_SPEC_OPTION_ID,o.SELECTED_OPTION_TEXT_SNAPSHOT FROM dbo.REQUISITION_ITEM_SPEC s LEFT JOIN dbo.REQUISITION_ITEM_SPEC_OPTION o ON o.REQ_ITEM_SPEC_ID=s.REQ_ITEM_SPEC_ID JOIN dbo.REQUISITION_ITEM i ON i.REQ_ITEM_ID=s.REQ_ITEM_ID WHERE i.REQUISITION_ID=@RequisitionId ORDER BY s.REQ_ITEM_ID,s.DISPLAY_ORDER_SNAPSHOT; SELECT * FROM dbo.APPROVAL_ACTION WHERE REQUISITION_ID=@RequisitionId ORDER BY ACTION_DATETIME; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Requisition_Search @RequisitionNo VARCHAR(30)=NULL,@OrgUnitId BIGINT=NULL,@AssetId BIGINT=NULL,@ReqType VARCHAR(20)=NULL,@CurrentStatus VARCHAR(40)=NULL,@FromDate DATE=NULL,@ToDate DATE=NULL
AS BEGIN SET NOCOUNT ON; SELECT DISTINCT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,h.REQUESTED_ORG_UNIT_ID,o.ORG_UNIT_NAME,h.TOTAL_ESTIMATED_AMOUNT,h.CURRENT_STATUS FROM dbo.REQUISITION_HEADER h JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID JOIN dbo.REQUISITION_ITEM i ON i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1 WHERE (@RequisitionNo IS NULL OR h.REQUISITION_NO LIKE @RequisitionNo+'%') AND (@OrgUnitId IS NULL OR h.REQUESTED_ORG_UNIT_ID=@OrgUnitId) AND (@AssetId IS NULL OR i.ASSET_ID=@AssetId) AND (@ReqType IS NULL OR i.REQ_TYPE=@ReqType) AND (@CurrentStatus IS NULL OR h.CURRENT_STATUS=@CurrentStatus) AND (@FromDate IS NULL OR h.REQUESTED_DATE>=@FromDate) AND (@ToDate IS NULL OR h.REQUESTED_DATE<DATEADD(DAY,1,@ToDate)) ORDER BY h.REQUESTED_DATE DESC; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Requisition_Submit @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRY BEGIN TRAN; DECLARE @status VARCHAR(40),@requester VARCHAR(30); SELECT @status=CURRENT_STATUS,@requester=REQUESTED_BY_EMPLOYEE_ID FROM dbo.REQUISITION_HEADER WITH(UPDLOCK,HOLDLOCK) WHERE REQUISITION_ID=@RequisitionId AND IS_ACTIVE=1; IF @status IS NULL THROW 51001,'Requisition not found.',1; IF @requester<>@ActorEmployeeId THROW 51002,'Only the requester may submit.',1; IF @status NOT IN('DRAFT','MANAGER_RETURNED') THROW 51003,'Invalid requisition state for submit.',1; IF EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM i JOIN dbo.ASSET_SPEC_DEFINITION d ON d.ASSET_ID=i.ASSET_ID AND d.IS_ACTIVE=1 AND d.IS_MANDATORY=1 LEFT JOIN dbo.REQUISITION_ITEM_SPEC s ON s.REQ_ITEM_ID=i.REQ_ITEM_ID AND s.ASSET_SPEC_ID=d.ASSET_SPEC_ID WHERE i.REQUISITION_ID=@RequisitionId AND i.IS_ACTIVE=1 AND s.REQ_ITEM_SPEC_ID IS NULL) THROW 51000,'Mandatory item specifications are missing.',1; UPDATE dbo.REQUISITION_HEADER SET CURRENT_STATUS='SUBMITTED',MODIFIED_BY=@ActorEmployeeId,MODIFIED_DATE=SYSUTCDATETIME() WHERE REQUISITION_ID=@RequisitionId; INSERT dbo.REQUISITION_ASSIGNMENT(REQUISITION_ID,ASSIGNMENT_TYPE,ASSIGNED_TO_ORG_UNIT_ID,CREATED_BY) SELECT @RequisitionId,'MANAGER',REQUESTED_ORG_UNIT_ID,@ActorEmployeeId FROM dbo.REQUISITION_HEADER WHERE REQUISITION_ID=@RequisitionId; INSERT dbo.APPROVAL_ACTION(REQUISITION_ID,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,ACTION_ROLE,FROM_STAGE,TO_STAGE,REMARKS,BATCH_REFERENCE_ID) VALUES(@RequisitionId,'SUBMIT',@ActorEmployeeId,'MAKER','DRAFT','MANAGER',@Remarks,@BatchReferenceId); INSERT dbo.WORKFLOW_HISTORY(REQUISITION_ID,FROM_STAGE,TO_STAGE,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,REMARKS,BATCH_REFERENCE_ID) VALUES(@RequisitionId,'DRAFT','MANAGER','SUBMIT',@ActorEmployeeId,@Remarks,@BatchReferenceId); COMMIT; SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,@RequisitionId ENTITY_ID,(SELECT REQUISITION_NO FROM dbo.REQUISITION_HEADER WHERE REQUISITION_ID=@RequisitionId) REFERENCE_NO; END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SELECT CASE ERROR_NUMBER() WHEN 51000 THEN '001' WHEN 51001 THEN '002' WHEN 51002 THEN '003' WHEN 51003 THEN '004' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO; END CATCH END;
GO
